/**
 * Normalizes `config.password` to a non-empty list of valid passwords.
 * Throws before any unseal attempt, so invalid entries never go unchecked.
 */
function resolvePasswords(config: SessionConfig): string[] {
  const passwords = Array.isArray(config.password) ? config.password : [config.password];
  if (passwords.length === 0 || passwords.some((password) => typeof password !== "string")) {
    throw new Error("Session password is missing or invalid");
  }
  const { encryption, integrity } = { ...sealDefaults, ...config.seal };
  const minLength = Math.max(encryption.minPasswordlength, integrity.minPasswordlength);
  for (const password of passwords) {
    if (!password) {
      throw new Error("Empty password");
    }
    assertPasswordLength(password, minLength);
  }
  return passwords;
}

/**
 * Cookie expiry: whichever of the absolute lifetime and the idle window runs out
 * first, or none if neither is configured.
 */
function sessionExpires(session: Session<any>, config: SessionConfig): Date | undefined {
  const times: number[] = [];
  if (config.maxAge) {
    times.push(session.createdAt + config.maxAge * 1000);
  }
  if (config.idleTimeout) {
    times.push((session.lastSeenAt || session.createdAt) + config.idleTimeout * 1000);
  }
  return times.length > 0 ? new Date(Math.min(...times)) : undefined;
}

